export function openDb(path: string): Database.Database {
  const db = new Database(path);
  db.pragma("journal_mode = WAL");
  db.pragma("foreign_keys = ON");
  const migration = readFileSync(
    join(__dirname, "migrations", "001_init.sql"),
    "utf8"
  );
  db.exec(migration);
  return db;
}

const revokeFamily = (familyId: string): void => {
  db.prepare(
    "UPDATE token_families SET revoked_at = ? WHERE id = ?"
  ).run(Date.now(), familyId);
  db.prepare(
    "UPDATE refresh_tokens SET revoked_at = ? WHERE family_id = ? AND revoked_at IS NULL"
  ).run(Date.now(), familyId);
};

const isFamilyRevoked = (familyId: string): boolean => {
  const row = db
    .prepare<[string], { revoked_at: number | null }>(
      "SELECT revoked_at FROM token_families WHERE id = ?"
    )
    .get(familyId);
  return row == null || row.revoked_at != null;
};

try {
  const payload = await verifyAccessToken(token);
  const fid = payload["fid"] as string | undefined;
  if (!fid || repo.isFamilyRevoked(fid)) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }
  (req as Request & { userId: number }).userId = Number(payload.sub);
  next();

const rotate = async (oldToken: string) => {
  const row = repo.findByHash(sha256(oldToken));
  if (!row || row.expires_at < Date.now() || repo.isFamilyRevoked(row.family_id)) {
    throw new InvalidToken();
  }
  if (row.revoked_at) {
    repo.revokeFamily(row.family_id);
    throw new TokenReuseDetected();
  }
  repo.revoke(row.id);
  const user = await users.findById(row.user_id);
  const access = await signAccessToken(user, row.family_id);
  const refresh = newRefreshToken();
  repo.insert({
    familyId: row.family_id,
    userId: user.id,
    hash: sha256(refresh),
    expiresAt: Date.now() + REFRESH_TOKEN_TTL_DAYS * 24 * 60 * 60 * 1000,
  });
  return { access, refresh };
};

const logout = (_req: Request, res: Response): void => {
  res.clearCookie("rt");
  res.status(204).end();
};

const refresh = async (req: Request, res: Response): Promise<void> => {
  const oldToken = (req.cookies as Record<string, string>)["rt"];
  if (!oldToken) {
    res.status(401).json({ error: "No refresh token" });
    return;
  }
  try {
    const { access, refresh: newRefresh } = await tokenService.rotate(oldToken);
    res.cookie("rt", newRefresh, {
      httpOnly: true,
      sameSite: "strict",
      maxAge: REFRESH_TOKEN_TTL_DAYS * 24 * 60 * 60 * 1000,
    });
    res.json({ accessToken: access }); 
  } catch (err) {
    if (err instanceof InvalidToken || err instanceof TokenReuseDetected) {
      res.clearCookie("rt");
      res.status(401).json({ error: "Unauthorized" });
        return;
    }
    throw err;
  }
};

export async function signAccessToken(user: UserRow, familyId: string): Promise<string> {
  return new SignJWT({ sub: String(user.id), fid: familyId })
    .setProtectedHeader({ alg: "HS256" })
    .setExpirationTime(Math.floor(Date.now() / 1000) + ACCESS_TOKEN_TTL)
    .sign(secretBytes);
}
